"""Find the stretches of opening hours nobody covers."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans

def _outside(span: Span, hours: Span) -> bool:
    return span.start < hours.start or span.end > hours.end

def _check_inside(worked: List[Span], hours: Span):
    for span in worked:
        if _outside(span, hours):
            text = format_span(span)
            raise ValueError(f"{text} is outside hours")

def _uncovered(
    merged: List[Span], hours: Span
) -> List[Span]:
    starts = [hours.start] + [item.end for item in merged]
    stops = [item.start for item in merged] + [hours.end]
    pairs = zip(starts, stops)
    return [
        Span(*pair) for pair in pairs if pair[0] < pair[1]
    ]

def _label(gap: Span) -> str:
    text = format_span(gap)
    return f"gap {text} ({gap.minutes} min)"

# ---
def find_gaps(
    worked: Iterable[Span], opening: Span
) -> List[str]:
    """One label per gap; ValueError if outside."""
    worked = list(worked)
    _check_inside(worked, opening)
    gaps = _uncovered(merge_spans(worked), opening)
    return [_label(gap) for gap in gaps]

