import unittest

from hourglass.parsing import parse_span
from hourglass.gaps import find_gaps

OPEN = parse_span("09:00-17:00")

def gaps_for(*texts):
    spans = [parse_span(text) for text in texts]
    return find_gaps(spans, OPEN)

class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        self.assertEqual(
            gaps_for("09:00-12:00", "13:00-17:00"),
            ["gap 12:00-13:00 (60 min)"],
        )

    def test_gaps_at_both_ends(self):
        self.assertEqual(
            gaps_for("10:00-16:00"),
            [
                "gap 09:00-10:00 (60 min)",
                "gap 16:00-17:00 (60 min)",
            ],
        )

    def test_full_cover_has_no_gaps(self):
        result = gaps_for("09:00-13:00", "13:00-17:00")
        self.assertEqual(result, [])

    def test_overlaps_and_order_do_not_matter(self):
        result = gaps_for(
            "12:00-17:00", "09:00-13:00", "10:00-11:00"
        )
        self.assertEqual(result, [])

    def test_nobody_working_is_one_big_gap(self):
        self.assertEqual(
            gaps_for(), ["gap 09:00-17:00 (480 min)"]
        )

    def test_span_before_opening_raises(self):
        with self.assertRaises(ValueError):
            gaps_for("08:00-10:00")

    def test_span_after_closing_raises(self):
        with self.assertRaises(ValueError):
            gaps_for("16:00-18:00")

if __name__ == "__main__":
    unittest.main()
